-- NEW / UNAPPLIED. Physical FDM filament spools and immutable movement ledger.

ALTER TABLE public.materials
ADD CONSTRAINT materials_enterprise_id_id_key
UNIQUE (enterprise_id, id);
BEGIN;

ALTER TABLE public.enterprises ADD COLUMN IF NOT EXISTS low_spool_threshold_percent numeric(5,2) NOT NULL DEFAULT 20.00;
ALTER TABLE public.enterprises ADD CONSTRAINT enterprises_low_spool_threshold_check CHECK (low_spool_threshold_percent BETWEEN 0 AND 100);

CREATE TABLE public.filament_spools (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id uuid NOT NULL REFERENCES public.enterprises(id) ON DELETE RESTRICT,
 material_id uuid NOT NULL, internal_identifier varchar(120) NOT NULL,
 original_filament_grams numeric(12,3) NOT NULL, current_balance_grams numeric(12,3) NOT NULL,
 purchase_price numeric(12,2) NOT NULL, active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 0,
 create_attempt_id uuid NOT NULL, create_actor_id uuid NOT NULL REFERENCES public.users(id),
 create_internal_identifier varchar(120) NOT NULL, create_initial_balance_grams numeric(12,3) NOT NULL, create_purchase_price numeric(12,2) NOT NULL,
 created_at timestamptz NOT NULL DEFAULT pg_catalog.now(), updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
 FOREIGN KEY (enterprise_id,material_id) REFERENCES public.materials(enterprise_id,id),
 CHECK (pg_catalog.btrim(internal_identifier)=internal_identifier AND pg_catalog.length(internal_identifier) BETWEEN 1 AND 120),
 CHECK (original_filament_grams BETWEEN .001 AND 100000 AND original_filament_grams::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK (current_balance_grams BETWEEN 0 AND original_filament_grams AND current_balance_grams::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK (purchase_price BETWEEN 0 AND 1000000 AND purchase_price::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK (pg_catalog.btrim(create_internal_identifier)=create_internal_identifier AND pg_catalog.length(create_internal_identifier) BETWEEN 1 AND 120),
 CHECK (create_initial_balance_grams BETWEEN 0 AND original_filament_grams AND create_initial_balance_grams::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK (create_purchase_price BETWEEN 0 AND 1000000 AND create_purchase_price::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK (version>=0), UNIQUE(enterprise_id,id), UNIQUE(enterprise_id,internal_identifier), UNIQUE(enterprise_id,create_actor_id,create_attempt_id)
);
CREATE INDEX filament_spools_list_idx ON public.filament_spools(enterprise_id,active,created_at DESC,id DESC);
CREATE INDEX filament_spools_material_idx ON public.filament_spools(enterprise_id,material_id,active);

CREATE TABLE public.filament_spool_movements (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id uuid NOT NULL REFERENCES public.enterprises(id) ON DELETE RESTRICT,
 spool_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES public.users(id), movement_type text NOT NULL,
 quantity_grams numeric(12,3) NOT NULL, balance_before_grams numeric(12,3) NOT NULL, balance_after_grams numeric(12,3) NOT NULL,
 unit_cost_per_gram numeric(21,9) NOT NULL, movement_cost numeric(21,6) NOT NULL, reason varchar(500), attempt_id uuid NOT NULL,
 request_expected_version bigint NOT NULL, request_quantity_grams numeric(12,3), request_counted_balance_grams numeric(12,3), result_version bigint NOT NULL,
 created_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
 FOREIGN KEY(enterprise_id,spool_id) REFERENCES public.filament_spools(enterprise_id,id) ON DELETE RESTRICT,
 CHECK(movement_type IN ('opening','consumption','replenishment','adjustment')),
 CHECK((movement_type='opening' AND quantity_grams>=0) OR (movement_type='consumption' AND quantity_grams<0) OR (movement_type='replenishment' AND quantity_grams>0) OR (movement_type='adjustment' AND quantity_grams<>0)),
 CHECK(balance_before_grams>=0 AND balance_after_grams>=0 AND balance_after_grams=balance_before_grams+quantity_grams),
 CHECK((movement_type='opening' AND reason IS NULL) OR (movement_type<>'opening' AND reason IS NOT NULL AND pg_catalog.btrim(reason)=reason AND pg_catalog.length(reason) BETWEEN 1 AND 500)),
 CHECK(quantity_grams::text NOT IN ('NaN','Infinity','-Infinity') AND balance_before_grams::text NOT IN ('NaN','Infinity','-Infinity') AND balance_after_grams::text NOT IN ('NaN','Infinity','-Infinity') AND unit_cost_per_gram BETWEEN 0 AND 1000000000 AND unit_cost_per_gram::text NOT IN ('NaN','Infinity','-Infinity') AND movement_cost BETWEEN 0 AND 100000000000000 AND movement_cost::text NOT IN ('NaN','Infinity','-Infinity')),
 CHECK((movement_type='opening' AND balance_before_grams=0 AND request_expected_version=0 AND result_version=0 AND request_quantity_grams=quantity_grams AND request_counted_balance_grams IS NULL) OR (movement_type<>'opening' AND request_expected_version BETWEEN 0 AND 9223372036854775806 AND result_version::numeric=request_expected_version::numeric+1 AND ((movement_type IN ('consumption','replenishment') AND request_quantity_grams=pg_catalog.abs(quantity_grams) AND request_counted_balance_grams IS NULL) OR (movement_type='adjustment' AND request_quantity_grams IS NULL AND request_counted_balance_grams=balance_after_grams)))),
 UNIQUE(enterprise_id,actor_id,attempt_id)
);
CREATE INDEX filament_spool_movements_history_idx ON public.filament_spool_movements(enterprise_id,spool_id,created_at DESC,id DESC);
ALTER TABLE public.filament_spools OWNER TO postgres;
ALTER TABLE public.filament_spool_movements OWNER TO postgres;

CREATE FUNCTION public.protect_filament_spool_movements() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'filament_spool_movements_immutable' USING ERRCODE='42501'; END $$;
CREATE TRIGGER protect_filament_spool_movements_trg BEFORE UPDATE OR DELETE ON public.filament_spool_movements FOR EACH ROW EXECUTE FUNCTION public.protect_filament_spool_movements();
CREATE FUNCTION public.internal_filament_spool_touch() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF NEW.enterprise_id IS DISTINCT FROM OLD.enterprise_id OR NEW.material_id IS DISTINCT FROM OLD.material_id OR NEW.original_filament_grams IS DISTINCT FROM OLD.original_filament_grams OR NEW.purchase_price IS DISTINCT FROM OLD.purchase_price OR NEW.create_attempt_id IS DISTINCT FROM OLD.create_attempt_id OR NEW.create_actor_id IS DISTINCT FROM OLD.create_actor_id OR NEW.create_internal_identifier IS DISTINCT FROM OLD.create_internal_identifier OR NEW.create_initial_balance_grams IS DISTINCT FROM OLD.create_initial_balance_grams OR NEW.create_purchase_price IS DISTINCT FROM OLD.create_purchase_price THEN RAISE EXCEPTION 'filament_spool_structural_fields_immutable' USING ERRCODE='42501'; END IF;
 NEW.updated_at:=pg_catalog.now(); NEW.version:=OLD.version+1; RETURN NEW; END $$;
CREATE TRIGGER filament_spools_touch BEFORE UPDATE ON public.filament_spools FOR EACH ROW EXECUTE FUNCTION public.internal_filament_spool_touch();

-- Preserve every prior permission and add only spool permissions.
CREATE OR REPLACE FUNCTION private.can_access_enterprise(p_enterprise_id uuid,p_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT CASE WHEN p_enterprise_id IS NULL OR p_permission IS NULL THEN false ELSE (SELECT count(*)=1 FROM public.enterprise_members em JOIN public.enterprises e ON e.id=em.enterprise_id WHERE em.user_id=private.current_internal_user_id() AND em.status='active' AND e.status='active') AND EXISTS(SELECT 1 FROM public.enterprise_members em JOIN public.users u ON u.id=em.user_id JOIN public.enterprises e ON e.id=em.enterprise_id WHERE em.enterprise_id=p_enterprise_id AND em.user_id=private.current_internal_user_id() AND em.status='active' AND u.status='active' AND NOT u.must_change_password AND e.status='active' AND CASE p_permission
 WHEN 'products.read' THEN em.role IN ('owner','admin','operator') WHEN 'products.write' THEN em.role IN ('owner','admin','operator') WHEN 'products.delete' THEN em.role IN ('owner','admin') WHEN 'catalogs.read' THEN em.role IN ('owner','admin','operator') WHEN 'catalogs.write' THEN em.role IN ('owner','admin','operator') WHEN 'catalogs.delete' THEN em.role IN ('owner','admin') WHEN 'filters.read' THEN em.role IN ('owner','admin','operator') WHEN 'filters.write' THEN em.role IN ('owner','admin','operator') WHEN 'filters.delete' THEN em.role IN ('owner','admin') WHEN 'sales.read' THEN em.role IN ('owner','admin','operator') WHEN 'sales.write' THEN em.role IN ('owner','admin','operator') WHEN 'sales.delete' THEN em.role IN ('owner','admin') WHEN 'printers.read' THEN em.role IN ('owner','admin','operator') WHEN 'printers.write' THEN em.role IN ('owner','admin') WHEN 'printers.archive' THEN em.role IN ('owner','admin') WHEN 'materials.read' THEN em.role IN ('owner','admin','operator') WHEN 'materials.write' THEN em.role IN ('owner','admin') WHEN 'materials.archive' THEN em.role IN ('owner','admin') WHEN 'pricing.read' THEN em.role IN ('owner','admin','operator') WHEN 'pricing.write' THEN em.role IN ('owner','admin','operator') WHEN 'pricing.apply' THEN em.role IN ('owner','admin','operator') WHEN 'enterprise.manage' THEN em.role='owner' WHEN 'members.manage_admins' THEN em.role='owner' WHEN 'members.manage_operators' THEN em.role IN ('owner','admin') WHEN 'spools.read' THEN em.role IN ('owner','admin','operator') WHEN 'spools.write' THEN em.role IN ('owner','admin','operator') WHEN 'spools.archive' THEN em.role IN ('owner','admin') ELSE false END) END $$;

-- Lock order for spool mutations: global membership -> actor -> identity -> user -> membership -> enterprise.
-- The global membership advisory transaction lock is held through commit and serializes every mutation, including missing attempt checks and identifier checks; no additional spool-specific advisory keys are needed.
CREATE FUNCTION private.lock_filament_spool_context(p_permission text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_uid uuid:=auth.uid(); v_issuer text:=auth.jwt()->>'iss'; v_context record; v_identity public.auth_identities%ROWTYPE; v_user public.users%ROWTYPE; v_member public.enterprise_members%ROWTYPE; v_enterprise public.enterprises%ROWTYPE;
BEGIN
 IF p_permission IS NULL OR p_permission NOT IN ('spools.write','spools.archive','enterprise.manage') OR v_uid IS NULL OR v_issuer IS NULL OR pg_catalog.btrim(v_issuer)='' THEN RETURN NULL; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('modulus:enterprise-management:all-members',0));
 SELECT context.* INTO v_context FROM public.get_my_access_context() AS context; IF NOT FOUND OR v_context.state IS DISTINCT FROM 'business_ready' THEN RETURN NULL; END IF;
 IF NOT EXISTS (SELECT 1 FROM private.auth_issuer_config AS issuer WHERE issuer.issuer=v_issuer AND issuer.provider='supabase' AND issuer.status='active') THEN RETURN NULL; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('modulus:employee-provisioning:actor:'||v_issuer||':'||v_uid::text,0));
 SELECT identity.* INTO v_identity FROM public.auth_identities AS identity JOIN private.auth_issuer_config AS issuer ON issuer.issuer=identity.issuer AND issuer.provider='supabase' AND issuer.status='active' WHERE identity.provider='supabase' AND identity.issuer=v_issuer AND identity.subject=v_uid::text AND identity.status='active' FOR UPDATE OF identity;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT person.* INTO v_user FROM public.users AS person WHERE person.id=v_identity.user_id FOR UPDATE; IF NOT FOUND OR v_user.status<>'active' OR v_user.must_change_password THEN RETURN NULL; END IF;
 SELECT member.* INTO v_member FROM public.enterprise_members AS member WHERE member.user_id=v_user.id AND member.enterprise_id=v_context.enterprise_id AND member.status='active' FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF;
 IF (SELECT pg_catalog.count(*) FROM public.enterprise_members AS other_member JOIN public.enterprises AS other_enterprise ON other_enterprise.id=other_member.enterprise_id WHERE other_member.user_id=v_user.id AND other_member.status='active' AND other_enterprise.status='active')<>1 THEN RETURN NULL; END IF;
 SELECT enterprise.* INTO v_enterprise FROM public.enterprises AS enterprise WHERE enterprise.id=v_member.enterprise_id AND enterprise.status='active' FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT context.* INTO v_context FROM public.get_my_access_context() AS context;
 IF NOT FOUND OR v_context.state IS DISTINCT FROM 'business_ready' OR v_context.user_id IS DISTINCT FROM v_user.id OR v_context.membership_id IS DISTINCT FROM v_member.id OR v_context.enterprise_id IS DISTINCT FROM v_enterprise.id OR NOT private.can_access_enterprise(v_enterprise.id,p_permission) THEN RETURN NULL; END IF;
 RETURN v_enterprise.id;
END $$;

CREATE FUNCTION private.read_filament_spool_context(p_permission text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_context record;
BEGIN
 IF p_permission IS DISTINCT FROM 'spools.read' THEN RETURN NULL; END IF;
 SELECT context.* INTO v_context FROM public.get_my_access_context() AS context;
 IF NOT FOUND OR v_context.state IS DISTINCT FROM 'business_ready' OR NOT private.can_access_enterprise(v_context.enterprise_id,p_permission) THEN RETURN NULL; END IF;
 RETURN v_context.enterprise_id;
END $$;

ALTER TABLE public.filament_spools ENABLE ROW LEVEL SECURITY; ALTER TABLE public.filament_spool_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY filament_spools_read ON public.filament_spools FOR SELECT TO authenticated USING(private.can_access_enterprise(enterprise_id,'spools.read'));
CREATE POLICY filament_spool_movements_read ON public.filament_spool_movements FOR SELECT TO authenticated USING(private.can_access_enterprise(enterprise_id,'spools.read'));
REVOKE ALL ON public.filament_spools,public.filament_spool_movements FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.filament_spools,public.filament_spool_movements TO authenticated;

CREATE FUNCTION public.create_filament_spool(p_attempt_id uuid,p_material_id uuid,p_internal_identifier text,p_original_grams numeric,p_initial_balance_grams numeric,p_purchase_price numeric) RETURNS TABLE(status text,spool_id uuid,version bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid;a uuid;s public.filament_spools%ROWTYPE;m public.materials%ROWTYPE;u numeric(21,9);c numeric(21,6); n text; BEGIN
 IF p_attempt_id IS NULL OR p_material_id IS NULL OR p_internal_identifier IS NULL OR p_original_grams IS NULL OR p_initial_balance_grams IS NULL OR p_purchase_price IS NULL OR p_original_grams::text IN ('NaN','Infinity','-Infinity') OR p_initial_balance_grams::text IN ('NaN','Infinity','-Infinity') OR p_purchase_price::text IN ('NaN','Infinity','-Infinity') OR pg_catalog.scale(p_original_grams)>3 OR pg_catalog.scale(p_initial_balance_grams)>3 OR pg_catalog.scale(p_purchase_price)>2 OR p_original_grams NOT BETWEEN .001 AND 100000 OR p_initial_balance_grams NOT BETWEEN 0 AND p_original_grams OR p_purchase_price NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF;
 n:=pg_catalog.btrim(p_internal_identifier); IF n='' OR pg_catalog.length(n)>120 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF; e:=private.lock_filament_spool_context('spools.write'); IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF; a:=private.current_internal_user_id();
 SELECT spool.* INTO s FROM public.filament_spools AS spool WHERE spool.enterprise_id=e AND spool.create_actor_id=a AND spool.create_attempt_id=p_attempt_id FOR UPDATE OF spool; IF FOUND THEN IF s.material_id=p_material_id AND s.create_internal_identifier=n AND s.original_filament_grams=p_original_grams AND s.create_initial_balance_grams=p_initial_balance_grams AND s.create_purchase_price=p_purchase_price THEN RETURN QUERY SELECT 'idempotent',s.id,0::bigint; RETURN; END IF; RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505'; END IF;
 IF EXISTS(SELECT 1 FROM public.filament_spools WHERE enterprise_id=e AND internal_identifier=n) THEN RAISE EXCEPTION 'identifier_conflict' USING ERRCODE='23505'; END IF;
 SELECT material.* INTO m FROM public.materials AS material WHERE material.enterprise_id=e AND material.id=p_material_id FOR UPDATE OF material; IF NOT FOUND OR NOT m.active THEN RAISE EXCEPTION 'material_unavailable' USING ERRCODE='P0001'; END IF;
 INSERT INTO public.filament_spools(enterprise_id,material_id,internal_identifier,original_filament_grams,current_balance_grams,purchase_price,create_attempt_id,create_actor_id,create_internal_identifier,create_initial_balance_grams,create_purchase_price) VALUES(e,p_material_id,n,p_original_grams,p_initial_balance_grams,p_purchase_price,p_attempt_id,a,n,p_initial_balance_grams,p_purchase_price) RETURNING * INTO s;
 u:=pg_catalog.round(p_purchase_price/p_original_grams,9); c:=pg_catalog.round(p_initial_balance_grams*p_purchase_price/p_original_grams,6); INSERT INTO public.filament_spool_movements(enterprise_id,spool_id,actor_id,movement_type,quantity_grams,balance_before_grams,balance_after_grams,unit_cost_per_gram,movement_cost,reason,attempt_id,request_expected_version,request_quantity_grams,request_counted_balance_grams,result_version) VALUES(e,s.id,a,'opening',p_initial_balance_grams,0,p_initial_balance_grams,u,c,NULL,p_attempt_id,0,p_initial_balance_grams,NULL,0); RETURN QUERY SELECT 'created',s.id,0::bigint; END $$;

CREATE FUNCTION public.create_filament_spool_movement(p_attempt_id uuid,p_spool_id uuid,p_expected_version bigint,p_movement_type text,p_quantity_grams numeric,p_counted_balance_grams numeric,p_reason text) RETURNS TABLE(status text,movement_id uuid,spool_id uuid,version bigint,balance_grams numeric) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid;a uuid;s public.filament_spools%ROWTYPE;x public.filament_spool_movements%ROWTYPE;q numeric(12,3);b numeric(12,3);nb numeric(12,3);u numeric(21,9);c numeric(21,6);r text; BEGIN
 IF p_attempt_id IS NULL OR p_spool_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0 OR p_movement_type IS NULL OR p_movement_type NOT IN ('consumption','replenishment','adjustment') OR p_reason IS NULL OR pg_catalog.btrim(p_reason)='' OR pg_catalog.length(p_reason)>500 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF; r:=pg_catalog.btrim(p_reason); e:=private.lock_filament_spool_context('spools.write'); IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF; a:=private.current_internal_user_id();
 SELECT movement.* INTO x FROM public.filament_spool_movements AS movement WHERE movement.enterprise_id=e AND movement.actor_id=a AND movement.attempt_id=p_attempt_id FOR UPDATE OF movement; IF FOUND THEN IF x.spool_id=p_spool_id AND x.movement_type=p_movement_type AND x.request_expected_version=p_expected_version AND x.request_quantity_grams IS NOT DISTINCT FROM p_quantity_grams AND x.request_counted_balance_grams IS NOT DISTINCT FROM p_counted_balance_grams AND x.reason=r THEN RETURN QUERY SELECT 'idempotent',x.id,x.spool_id,x.result_version,x.balance_after_grams; RETURN; END IF; RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505'; END IF;
 -- no_change adjustments are deliberately not persisted; a later retry sees version_conflict if another write won.
 SELECT spool.* INTO s FROM public.filament_spools AS spool WHERE spool.id=p_spool_id AND spool.enterprise_id=e FOR UPDATE OF spool; IF NOT FOUND OR NOT s.active THEN RAISE EXCEPTION 'spool_unavailable' USING ERRCODE='P0002'; END IF; IF s.version<>p_expected_version THEN RAISE EXCEPTION 'version_conflict' USING ERRCODE='40001'; END IF; b:=s.current_balance_grams;
 IF p_movement_type='adjustment' THEN IF p_counted_balance_grams IS NULL OR p_counted_balance_grams::text IN ('NaN','Infinity','-Infinity') OR pg_catalog.scale(p_counted_balance_grams)>3 OR p_counted_balance_grams NOT BETWEEN 0 AND s.original_filament_grams OR p_quantity_grams IS NOT NULL THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF; nb:=p_counted_balance_grams; q:=nb-b; IF q=0 THEN RETURN QUERY SELECT 'no_change',NULL::uuid,s.id,s.version,b; RETURN; END IF; ELSE IF p_quantity_grams IS NULL OR p_quantity_grams::text IN ('NaN','Infinity','-Infinity') OR pg_catalog.scale(p_quantity_grams)>3 OR p_quantity_grams NOT BETWEEN .001 AND 100000 OR p_counted_balance_grams IS NOT NULL THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF; q:=CASE WHEN p_movement_type='consumption' THEN -p_quantity_grams ELSE p_quantity_grams END; nb:=b+q; END IF;
 IF nb<0 THEN RAISE EXCEPTION 'insufficient_balance' USING ERRCODE='P0003'; END IF; IF nb>s.original_filament_grams THEN RAISE EXCEPTION 'capacity_exceeded' USING ERRCODE='P0004'; END IF; u:=pg_catalog.round(s.purchase_price/s.original_filament_grams,9); c:=pg_catalog.round(pg_catalog.abs(q)*s.purchase_price/s.original_filament_grams,6); UPDATE public.filament_spools AS sp SET current_balance_grams=nb WHERE sp.id=s.id RETURNING sp.version INTO s.version;
 INSERT INTO public.filament_spool_movements AS movement(enterprise_id,spool_id,actor_id,movement_type,quantity_grams,balance_before_grams,balance_after_grams,unit_cost_per_gram,movement_cost,reason,attempt_id,request_expected_version,request_quantity_grams,request_counted_balance_grams,result_version) VALUES(e,s.id,a,p_movement_type,q,b,nb,u,c,r,p_attempt_id,p_expected_version,p_quantity_grams,p_counted_balance_grams,s.version) RETURNING movement.id INTO x.id; RETURN QUERY SELECT 'created',x.id,s.id,s.version,nb; END $$;

CREATE FUNCTION public.set_filament_spool_active(p_spool_id uuid,p_expected_version bigint,p_active boolean) RETURNS TABLE(status text,spool_id uuid,version bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid;s public.filament_spools%ROWTYPE; BEGIN IF p_spool_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0 OR p_active IS NULL THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF; e:=private.lock_filament_spool_context('spools.archive'); IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF; SELECT spool.* INTO s FROM public.filament_spools AS spool WHERE spool.id=p_spool_id AND spool.enterprise_id=e FOR UPDATE OF spool; IF NOT FOUND THEN RAISE EXCEPTION 'spool_unavailable' USING ERRCODE='P0002'; END IF; IF s.version<>p_expected_version THEN RAISE EXCEPTION 'version_conflict' USING ERRCODE='40001'; END IF; IF s.active=p_active THEN RETURN QUERY SELECT 'no_change',s.id,s.version; RETURN; END IF; UPDATE public.filament_spools AS sp SET active=p_active WHERE sp.id=s.id RETURNING sp.version INTO s.version; RETURN QUERY SELECT 'updated',s.id,s.version; END $$;
CREATE FUNCTION public.update_filament_spool_identity(p_spool_id uuid,p_expected_version bigint,p_internal_identifier text) RETURNS TABLE(status text,spool_id uuid,version bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid;s public.filament_spools%ROWTYPE;n text; BEGIN IF p_spool_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0 OR p_internal_identifier IS NULL THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF;n:=pg_catalog.btrim(p_internal_identifier);IF n='' OR pg_catalog.length(n)>120 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023'; END IF;e:=private.lock_filament_spool_context('spools.archive');IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';END IF;SELECT spool.* INTO s FROM public.filament_spools AS spool WHERE spool.id=p_spool_id AND spool.enterprise_id=e FOR UPDATE OF spool;IF NOT FOUND THEN RAISE EXCEPTION 'spool_unavailable' USING ERRCODE='P0002';END IF;IF NOT s.active THEN RAISE EXCEPTION 'spool_unavailable' USING ERRCODE='P0002'; END IF; IF s.version<>p_expected_version THEN RAISE EXCEPTION 'version_conflict' USING ERRCODE='40001';END IF;IF s.internal_identifier=n THEN RETURN QUERY SELECT 'no_change',s.id,s.version;RETURN;END IF;IF EXISTS(SELECT 1 FROM public.filament_spools WHERE enterprise_id=e AND internal_identifier=n AND id<>s.id) THEN RAISE EXCEPTION 'identifier_conflict' USING ERRCODE='23505';END IF;UPDATE public.filament_spools AS sp SET internal_identifier=n WHERE sp.id=s.id RETURNING sp.version INTO s.version;RETURN QUERY SELECT 'updated',s.id,s.version;END $$;

CREATE FUNCTION public.get_my_spool_config() RETURNS TABLE(low_spool_threshold_percent numeric(5,2),version bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid; BEGIN e:=private.read_filament_spool_context('spools.read');IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';END IF;RETURN QUERY SELECT en.low_spool_threshold_percent,en.version FROM public.enterprises en WHERE en.id=e;END $$;
CREATE FUNCTION public.update_my_spool_threshold(p_threshold numeric,p_expected_version bigint) RETURNS TABLE(status text,version bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE x public.enterprises%ROWTYPE;e uuid;BEGIN IF p_threshold IS NULL OR p_threshold::text IN ('NaN','Infinity','-Infinity') OR pg_catalog.scale(p_threshold)>2 OR p_threshold NOT BETWEEN 0 AND 100 OR p_expected_version IS NULL OR p_expected_version<0 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';END IF;e:=private.lock_filament_spool_context('enterprise.manage');IF e IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';END IF;SELECT * INTO x FROM public.enterprises en WHERE en.id=e FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';END IF;IF x.version<>p_expected_version THEN RETURN QUERY SELECT 'version_conflict',x.version;RETURN;END IF;IF x.low_spool_threshold_percent=p_threshold THEN RETURN QUERY SELECT 'no_change',x.version;RETURN;END IF;UPDATE public.enterprises en SET low_spool_threshold_percent=p_threshold WHERE en.id=x.id RETURNING en.version INTO x.version;RETURN QUERY SELECT 'updated',x.version;END $$;

ALTER FUNCTION public.protect_filament_spool_movements() OWNER TO postgres; ALTER FUNCTION public.internal_filament_spool_touch() OWNER TO postgres; ALTER FUNCTION private.can_access_enterprise(uuid,text) OWNER TO postgres; ALTER FUNCTION private.lock_filament_spool_context(text) OWNER TO postgres; ALTER FUNCTION private.read_filament_spool_context(text) OWNER TO postgres; ALTER FUNCTION public.create_filament_spool(uuid,uuid,text,numeric,numeric,numeric) OWNER TO postgres; ALTER FUNCTION public.create_filament_spool_movement(uuid,uuid,bigint,text,numeric,numeric,text) OWNER TO postgres; ALTER FUNCTION public.set_filament_spool_active(uuid,bigint,boolean) OWNER TO postgres; ALTER FUNCTION public.update_filament_spool_identity(uuid,bigint,text) OWNER TO postgres; ALTER FUNCTION public.get_my_spool_config() OWNER TO postgres; ALTER FUNCTION public.update_my_spool_threshold(numeric,bigint) OWNER TO postgres;
REVOKE ALL ON FUNCTION private.can_access_enterprise(uuid,text),private.lock_filament_spool_context(text),private.read_filament_spool_context(text),public.protect_filament_spool_movements(),public.internal_filament_spool_touch() FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.create_filament_spool(uuid,uuid,text,numeric,numeric,numeric),public.create_filament_spool_movement(uuid,uuid,bigint,text,numeric,numeric,text),public.set_filament_spool_active(uuid,bigint,boolean),public.update_filament_spool_identity(uuid,bigint,text),public.get_my_spool_config(),public.update_my_spool_threshold(numeric,bigint) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION private.can_access_enterprise(uuid,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.create_filament_spool(uuid,uuid,text,numeric,numeric,numeric),public.create_filament_spool_movement(uuid,uuid,bigint,text,numeric,numeric,text),public.set_filament_spool_active(uuid,bigint,boolean),public.update_filament_spool_identity(uuid,bigint,text),public.get_my_spool_config(),public.update_my_spool_threshold(numeric,bigint) TO authenticated;

-- Manual SQL test plan (run in an isolated local database with authenticated JWT context):
--  1 create valid spool: created/version 0; 2 identical actor retry: idempotent/version 0;
--  3 changed create payload: idempotency_conflict; 4 archived material: material_unavailable;
--  5 duplicate identifier: identifier_conflict; 6 opening ledger has before=0/result=0;
--  7 valid consumption: created/version 1; 8 exact movement retry after further write: original result version;
--  9 changed movement retry: idempotency_conflict; 10 stale expected version: version_conflict;
-- 11 adjustment equal balance: no_change and no ledger row; then write and retry: version_conflict;
-- 12 insufficient consumption/capacity replenishment: respective errors; 13 NaN/Infinity/excess scale: invalid_input;
-- 14 archive then movement denied, restore, archived identity update denied, and UPDATE/DELETE ledger denied;
-- 15 PENDING / NOT RUN: two sessions submit the same create attempt and confirm one created plus one idempotent result;
-- 16 PENDING / NOT RUN: two sessions submit competing consumption movements and confirm serialized versions/balances;
-- 17 PENDING / NOT RUN: change membership/auth state concurrently and confirm mutation context revalidation denies stale access;
-- 18 PENDING / NOT RUN: read config while a mutation is active and confirm no write row locks are taken;
-- 19 PENDING / NOT RUN: NULL movement type and NULL/type-specific parameter cases return invalid_input;
-- 20 PENDING / NOT RUN: preserved exact retry, changed retry, no_change, insufficient-balance, and capacity-error scenarios.
COMMIT;
